<!doctype html><html><head><meta charset="utf-8"><title>Parameters</title>@vite(['resources/css/app.css'])</head><body><main class="parameter-page"><header class="parameter-top"><a href="{{ route('dashboard') }}">Home</a><strong>Settings › Parameters</strong></header><section class="parameter-filters"><label>Category <select id="cat"><option selected>Procedure</option><option>Taxonomy</option><option>Rating</option><option>Scoring</option><option>Drift</option></select></label><label>Reference <select><option>All references</option><option>System default</option></select></label><label>Search <input id="q" placeholder="Code, description…"></label><button type="button" id="search">Search</button></section><section class="parameter-grid"><table><thead><tr><th>No.</th><th>Code</th><th>Description</th><th>Disable</th><th>Updated By</th><th>Updated Time</th><th>Remarks</th></tr></thead><tbody id="parameters"><tr><td colspan="7">Loading procedures…</td></tr></tbody></table></section></main><script>const h=parameters,fix=[['Rating','0','Cultural loss'],['Rating','1','Partial retention'],['Rating','2','Full retention'],['Scoring','SKB','Cultural fidelity'],['Scoring','IKG','PA/PB/PC instability']];function a(c,x,d,r){let z=document.createElement('tr');z.dataset.cat=c;z.innerHTML='<td></td><td>'+x+'</td><td>'+d+'</td><td><input type="checkbox"></td><td>System</td><td>Live</td><td>'+r+'</td>';h.append(z)}async function load(){let[p,c,d]=await Promise.all(['/api/v1/prompt-versions/catalog','/api/v1/taxonomy/cultural-categories','/api/v1/taxonomy/drift-types'].map(u=>fetch(u,{credentials:'same-origin'}).then(x=>x.json())));h.replaceChildren();p.forEach(x=>a('Procedure',x.template.code+' v'+x.version_number,x.template.name,x.prompt_body));c.forEach(x=>a('Taxonomy',x.code,x.name,'Cultural taxonomy'));d.forEach(x=>a('Drift',x.code,x.name,'Drift type'));fix.forEach(x=>a(...x));[...h.rows].forEach((x,i)=>x.cells[0].textContent=i+1);filter()}function filter(){let c=cat.value,q=document.getElementById('q').value.toLowerCase();[...h.rows].forEach(x=>x.hidden=(x.dataset.cat!==c)||(q&&!x.innerText.toLowerCase().includes(q)))}cat.onchange=filter;search.onclick=filter;load()</script></body></html>
